for title, artist in songs_to_archive:
    search_result = apis.spotify.search_songs(query=title, access_token=login_result["access_token"])
    # Find the song that matches both title and artist
    found = None
    for song in search_result:
        if song["title"].lower() == title.lower():
            # Check if any artist matches
            for art in song["artists"]:
                if art["name"].lower() == artist.lower():
                    found = song["song_id"]
                    break
            if found:
                break
    if found:
