# Let's search for each song in songs_to_archive to get their song_ids
# We'll use the first artist in the query to narrow down results
song_id_map = {}
for song in songs_to_archive:
    title = song['title']
    artist = song['artists'][0]  # use first artist for query
    query = f"{title} {artist}"
    results = apis.spotify.search_songs(query=query, access_token=spotify_token)
    # Find exact match
    found = None
    for r in results:
        if r['title'].lower() == title.lower():
            # Check if all artists in song['artists'] are present in r['artists']
            r_artists = [a['name'] for a in r['artists']]
            if all(a in r_artists for a in song['artists']):
                found = r['song_id']
                break
    if found is not None:
        song_id_map[title] = found
        print(f"Found: {title} -> {found}")
    else:
        print(f"NOT FOUND: {title}")

print("Total found:", len(song_id_map))

