# Let's build a mapping of song title+artists to song_id by searching for each song
# We'll use the search_songs API and match by title and artists
song_id_map = {}
for song in songs_to_archive:
    title = song["title"]
    artists = song["artists"]
    # Build query with title and first artist
    query = title + " " + artists[0]
    results = apis.spotify.search_songs(query=query, access_token=spotify_token)
    # Find the result that matches title and all artists
    matched = None
    for r in results:
        if r["title"].lower() == title.lower():
            result_artists = [a["name"] for a in r["artists"]]
            if all(any(ra.lower() == a.lower() for ra in result_artists) for a in artists):
                matched = r
                break
    if matched:
        song_id_map[(title, tuple(artists))] = matched["song_id"]
    else:
        print(f"Could not find song: {title} by {artists}")

print("Song ID map:")
for key, val in song_id_map.items():
    print(key, "->", val)

