steps.code:
# Parse the note content to extract songs
content = note['content']
lines = content.strip().split('\n')
# First line is the header "# Songs I have Liked"
songs = []
for line in lines[1:]:
    line = line.strip()
    if not line:
        continue
    # Remove leading "- "
    if line.startswith('- '):
        line = line[2:]
    # Split by " BY " to get title and rest
    if ' BY ' in line:
        title_part, rest = line.split(' BY ', 1)
        # rest contains artists and RELEASED_AT
        # Split by " RELEASED_AT " to get artists and release
        if ' RELEASED_AT ' in rest:
            artists_part, release = rest.split(' RELEASED_AT ', 1)
            artists = [a.strip() for a in artists_part.split(',')]
            songs.append({
                'title': title_part.strip(),
                'artists': artists,
                'release': release.strip()
            })
        else:
            # malformed
            print("Malformed line:", line)
    else:
        print("No BY found:", line)
print("Parsed songs:")
for s in songs:
    print(s)

