liked_song_ids = set()
for song in liked_songs_page:
    liked_song_ids.add(song['song_id'])
for song in liked_songs_page_2:
    liked_song_ids.add(song['song_id'])

# Check each song in the updated queue
all_liked = True
for song in updated_queue:
    if song['song_id'] not in liked_song_ids:
        print(f"Song {song['song_id']} ({song['title']}) is NOT liked!")
        all_liked = False

if all_liked:
    print("All remaining songs in the queue are liked.")
else:
    print("Some songs are still not liked - need to remove them.")

